package com.fakelegacy.customer;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class CreditController {

    @Autowired
    private CustomerDao customerDao;

    // U7
    @GetMapping("/customers/{id}/credit")
    public Map<String, Object> credit(@PathVariable("id") long id) {
        Customer c = customerDao.findById(id);
        if (c == null) {
            return Responses.error("customer not found");
        }
        return view(c);
    }

    // U8: negative amount releases outstanding credit
    @PostMapping("/customers/{id}/credit/consume")
    public Map<String, Object> consume(@PathVariable("id") long id, @RequestBody Map<String, Object> body) {
        if (customerDao.findById(id) == null) {
            return Responses.error("customer not found");
        }
        BigDecimal amount;
        try {
            amount = new BigDecimal(String.valueOf(body.get("amount"))).setScale(2, RoundingMode.HALF_UP);
        } catch (NumberFormatException e) {
            return Responses.error("amount must be a number");
        }
        if (amount.signum() == 0) {
            return Responses.error("amount must be non-zero");
        }
        if (amount.signum() > 0) {
            if (!customerDao.tryConsumeCredit(id, amount)) {
                return Responses.error("insufficient available credit");
            }
        } else if (!customerDao.tryReleaseCredit(id, amount)) {
            return Responses.error("cannot release more than the outstanding amount");
        }
        return view(customerDao.findById(id));
    }

    private Map<String, Object> view(Customer c) {
        Map<String, Object> res = Responses.ok();
        res.put("customerId", c.getId());
        res.put("creditLimit", c.getCreditLimit());
        res.put("creditOutstanding", c.getCreditOutstanding());
        res.put("creditAvailable", c.getCreditLimit().subtract(c.getCreditOutstanding()));
        return res;
    }
}
